CREATE DATABASE IF NOT EXISTS irigasi_cerdas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE irigasi_cerdas;
CREATE TABLE zones (id INT PRIMARY KEY, name VARCHAR(100), plant VARCHAR(100), moisture DECIMAL(5,2), status VARCHAR(30), device_status VARCHAR(30), soil_temp DECIMAL(5,2), last_updated VARCHAR(50), area VARCHAR(50), soil_type VARCHAR(100), water_need VARCHAR(50), target_moisture_min INT, target_moisture_max INT, moisture_min INT, moisture_mid INT, moisture_max INT, irrigation_duration INT, estimated_water DECIMAL(8,2), image TEXT);
CREATE TABLE zone_images (id INT AUTO_INCREMENT PRIMARY KEY, zone_id INT NOT NULL, image_url TEXT NOT NULL, sort_order INT NOT NULL, FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE);
CREATE TABLE sensors (id VARCHAR(50) PRIMARY KEY, zone_id INT NOT NULL, label VARCHAR(100), value DECIMAL(6,2), status VARCHAR(30), FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE);
CREATE TABLE moisture_history (id INT AUTO_INCREMENT PRIMARY KEY, zone_id INT NOT NULL, day_index INT NOT NULL, value DECIMAL(6,2), measured_at DATETIME(3) NULL, FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE);
CREATE TABLE temperature_history (id INT AUTO_INCREMENT PRIMARY KEY, zone_id INT NOT NULL, value DECIMAL(6,2) NOT NULL, measured_at DATETIME(3) NOT NULL, INDEX ix_temperature_history_zone_time (zone_id, measured_at), FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE);
CREATE TABLE schedules (id INT PRIMARY KEY AUTO_INCREMENT, zone_id INT, zone_name VARCHAR(100), plant VARCHAR(100), plant_type VARCHAR(100), image TEXT, time_text VARCHAR(10), duration INT, flow_rate DECIMAL(8,2), estimated_water DECIMAL(8,2), active BOOLEAN, mode VARCHAR(30));
CREATE TABLE schedule_days (schedule_id INT NOT NULL, day_name VARCHAR(10) NOT NULL, PRIMARY KEY(schedule_id, day_name), FOREIGN KEY(schedule_id) REFERENCES schedules(id) ON DELETE CASCADE);
CREATE TABLE notifications (id INT PRIMARY KEY, type VARCHAR(30), category VARCHAR(50), title VARCHAR(255), description TEXT, zone_id INT NULL, zone_name VARCHAR(100), plant VARCHAR(100), plant_type VARCHAR(100), moisture DECIMAL(6,2) NULL, threshold DECIMAL(6,2) NULL, image TEXT, event_date VARCHAR(30), time_text VARCHAR(10), is_read BOOLEAN);
CREATE TABLE history (id INT PRIMARY KEY, event_date VARCHAR(30), time_text VARCHAR(10), zone_id INT, zone_name VARCHAR(100), plant VARCHAR(100), image TEXT, moisture_before DECIMAL(6,2), moisture_after DECIMAL(6,2), duration INT, water_volume DECIMAL(8,2), method VARCHAR(30), status VARCHAR(30), started_at DATETIME NULL);
CREATE TABLE app_data (data_key VARCHAR(40) PRIMARY KEY, data JSON NOT NULL);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, email VARCHAR(150) UNIQUE, password_hash VARCHAR(128) NOT NULL, password_salt VARCHAR(64) NOT NULL, name VARCHAR(150) NOT NULL, role VARCHAR(50) NOT NULL DEFAULT 'Operator', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
